import java.util.*;

class Employee {

    static int nextId = 1001;
    static int count = 0;

    int id;
    String name;

    Employee(String name) {

        this.name = name;
        this.id = nextId;

        nextId++;
        count++;
    }

    static int getTotalEmployees() {

        return count;
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        for (int i = 0; i < n; i++) {

            String name = sc.next();

            Employee emp = new Employee(name);

            System.out.println(
                    emp.id + " " + emp.name);
        }

        System.out.println(
                "Total Employees: "
                + Employee.getTotalEmployees());
    }
}

