import java.util.*;

class Employee {

    static int count = 0;
    static double totalSalary = 0;

    double salary;

    Employee(double salary) {

        this.salary = salary;

        count++;
        totalSalary += salary;
    }

    static double getAverageSalary() {

        return totalSalary / count;
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        for (int i = 0; i < n; i++)
            new Employee(sc.nextDouble());

        System.out.println(
                "Average Salary: "
                + Employee.getAverageSalary());
    }
}

