solutionCode:
import java.util.*;

public class Main {

    static String compress(String s) {

        StringBuilder result =
                new StringBuilder();

        int count = 1;

        for (int i = 1; i <= s.length(); i++) {

            if (i < s.length()
                    && s.charAt(i)
                    == s.charAt(i - 1)) {

                count++;

            } else {

                result.append(
                        s.charAt(i - 1));

                result.append(count);

                count = 1;
            }
        }

        return result.toString();
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        String s = sc.next();

        System.out.println(compress(s));
    }
}

