import java.util.*;

public class Main {

    static boolean isAnagram(
            String a, String b) {

        if (a.length() != b.length())
            return false;

        int[] freq = new int[26];

        for (char c : a.toCharArray())
            freq[c - 'a']++;

        for (char c : b.toCharArray())
            freq[c - 'a']--;

        for (int value : freq) {

            if (value != 0)
                return false;
        }

        return true;
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        String a = sc.next();
        String b = sc.next();

        System.out.println(
                isAnagram(a, b)
                ? "Anagram"
                : "Not Anagram");
    }
}

