solutionCode:
import java.util.*;

public class Main {

    static boolean isPalindrome(String s) {

        StringBuilder clean =
                new StringBuilder();

        for (char c : s.toCharArray()) {

            if (Character.isLetterOrDigit(c)) {

                clean.append(
                        Character.toLowerCase(c));
            }
        }

        int left = 0;
        int right = clean.length() - 1;

        while (left < right) {

            if (clean.charAt(left)
                    != clean.charAt(right)) {

                return false;
            }

            left++;
            right--;
        }

        return true;
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        String s = sc.nextLine();

        System.out.println(
                isPalindrome(s)
                ? "Palindrome"
                : "Not Palindrome");
    }
}

