import java.util.*;

public class Main {

    static void spiral(int[][] matrix) {

        int top = 0;
        int bottom = matrix.length - 1;

        int left = 0;
        int right = matrix[0].length - 1;

        while (top <= bottom
                && left <= right) {

            for (int j = left; j <= right; j++)
                System.out.print(
                        matrix[top][j] + " ");

            top++;

            for (int i = top; i <= bottom; i++)
                System.out.print(
                        matrix[i][right] + " ");

            right--;

            if (top <= bottom) {

                for (int j = right;
                     j >= left;
                     j--) {

                    System.out.print(
                            matrix[bottom][j] + " ");
                }

                bottom--;
            }

            if (left <= right) {

                for (int i = bottom;
                     i >= top;
                     i--) {

                    System.out.print(
                            matrix[i][left] + " ");
                }

                left++;
            }
        }
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int r = sc.nextInt();
        int c = sc.nextInt();

        int[][] matrix = new int[r][c];

        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                matrix[i][j] = sc.nextInt();

        spiral(matrix);
    }
}

