import java.util.*;

public class Main {

    static int[] maximumRowSum(
            int[][] matrix) {

        int maxSum =
                Integer.MIN_VALUE;

        int rowNumber = 0;

        for (int i = 0;
             i < matrix.length;
             i++) {

            int sum = 0;

            for (int value : matrix[i])
                sum += value;

            if (sum > maxSum) {

                maxSum = sum;
                rowNumber = i + 1;
            }
        }

        return new int[]{
                rowNumber, maxSum
        };
    }

    public static void main(String[] args) {

