import java.util.*;

public class Main {

    static int findSaddlePoint(
            int[][] matrix) {

        int rows = matrix.length;
        int cols = matrix[0].length;

        for (int i = 0; i < rows; i++) {

            int minCol = 0;

            // Find minimum in current row
            for (int j = 1; j < cols; j++) {

                if (matrix[i][j]
                        < matrix[i][minCol]) {

                    minCol = j;
                }
            }

            boolean isMaximum = true;

            // Check whether it is maximum
            // in its column
            for (int k = 0; k < rows; k++) {

                if (matrix[k][minCol]
                        > matrix[i][minCol]) {

                    isMaximum = false;
                    break;
                }
            }

            if (isMaximum)
                return matrix[i][minCol];
        }

        return -1;
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int r = sc.nextInt();
        int c = sc.nextInt();

        int[][] matrix = new int[r][c];

        for (int i = 0; i < r; i++)
            for (int j = 0; j < c; j++)
                matrix[i][j] = sc.nextInt();

        int result =
                findSaddlePoint(matrix);

        if (result == -1)
            System.out.println(
                    "No Saddle Point");
        else
            System.out.println(
                    "Saddle Point: " + result);
    }
}

