import java.util.*;

public class Main {

    static int diagonalDifference(
            int[][] matrix) {

        int n = matrix.length;

        int primary = 0;
        int secondary = 0;

        for (int i = 0; i < n; i++) {

            primary += matrix[i][i];

            secondary +=
                    matrix[i][n - i - 1];
        }

        return Math.abs(
                primary - secondary);
    }

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int[][] matrix = new int[n][n];

        for (int i = 0; i < n; i++)
            for (int j = 0; j < n; j++)
                matrix[i][j] = sc.nextInt();

        System.out.println(
                diagonalDifference(matrix));
    }
}

