import java.util.*;

class NumberUtility {

    public static int maximum(int[] arr) {

        int max = arr[0];

        for (int value : arr)
            max = Math.max(max, value);

        return max;
    }

    public static int minimum(int[] arr) {

        int min = arr[0];

        for (int value : arr)
            min = Math.min(min, value);

        return min;
    }

    public static double average(int[] arr) {

        long sum = 0;

        for (int value : arr)
            sum += value;

        return (double) sum / arr.length;
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int[] arr = new int[n];

        for (int i = 0; i < n; i++)
            arr[i] = sc.nextInt();

        System.out.println(
                "Maximum: "
                + NumberUtility.maximum(arr));

        System.out.println(
                "Minimum: "
                + NumberUtility.minimum(arr));

        System.out.println(
                "Average: "
                + NumberUtility.average(arr));
    }
}

