import java.util.*;

class Student {

    private int[] marks;

    public void setMarks(int[] marks) {

        this.marks = marks;
    }

    public int[] getMarks() {

        return marks;
    }

    public double calculateAverage() {

        int sum = 0;

        for (int mark : marks)
            sum += mark;

        return (double) sum / marks.length;
    }

    public char calculateGrade() {

        double average =
                calculateAverage();

        if (average >= 90)
            return 'A';

        if (average >= 75)
            return 'B';

        if (average >= 60)
            return 'C';

        if (average >= 50)
            return 'D';

        return 'F';
    }
}

public class Main {

    public static void main(String[] args) {

        Scanner sc = new Scanner(System.in);

        int n = sc.nextInt();

        int[] marks = new int[n];

        for (int i = 0; i < n; i++)
            marks[i] = sc.nextInt();

        Student student = new Student();

        student.setMarks(marks);

        System.out.println(
                "Average: "
                + student.calculateAverage());

        System.out.println(
                "Grade: "
                + student.calculateGrade());
    }
}

