import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        StringBuilder sb = new StringBuilder();
        while (true) {
            sb.append(n);
            if (n == 1) break;
            sb.append(' ');
            if (n % 2 == 0) n /= 2;
            else n = 3 * n + 1;
        }
        System.out.println(sb.toString());
    }
}

