        int t = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        while (t-- > 0) {
            long y = sc.nextLong();
            long x = sc.nextLong();
            long z = Math.max(y, x);
            long z2 = (z - 1) * (z - 1);
            long ans;
            if (z % 2 == 0) {
                if (y == z) ans = z * z - x + 1;
                else ans = z2 + y;
            } else {
                if (x == z) ans = z * z - y + 1;
                else ans = z2 + x;
            }
            sb.append(ans).append('\n');
        }
        System.out.print(sb.toString());
    }
}

