import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long mod = 1000000007L;
        long[][] dp = new long[n][n];
        for (int r = 0; r < n; r++) {
            String row = sc.next();
            for (int c = 0; c < n; c++) {
                if (row.charAt(c) == '*') {
                    dp[r][c] = 0;
                } else if (r == 0 && c == 0) {
                    dp[r][c] = 1;
                } else {
                    long up = r > 0 ? dp[r - 1][c] : 0;
                    long left = c > 0 ? dp[r][c - 1] : 0;
                    dp[r][c] = (up + left) % mod;
                }
            }
        }
        System.out.println(dp[n - 1][n - 1]);
    }
}

