        int n = sc.nextInt();
        int m = sc.nextInt();
        char[][] g = new char[n][];
        int sr = 0, sc0 = 0, er = 0, ec = 0;
        for (int i = 0; i < n; i++) {
            g[i] = sc.next().toCharArray();
            for (int j = 0; j < m; j++) {
                if (g[i][j] == 'A') { sr = i; sc0 = j; }
                if (g[i][j] == 'B') { er = i; ec = j; }
            }
        }
        int[][] dist = new int[n][m];
        for (int[] row : dist) Arrays.fill(row, -1);
        dist[sr][sc0] = 0;
        int[] q = new int[n * m];
        int head = 0, tail = 0;
        q[tail++] = sr * m + sc0;
        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};
        while (head < tail) {
            int u = q[head++];
            int r = u / m, c = u % m;
            if (r == er && c == ec) break;
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr >= 0 && nr < n && nc >= 0 && nc < m && g[nr][nc] != '#' && dist[nr][nc] == -1) {
                    dist[nr][nc] = dist[r][c] + 1;
                    q[tail++] = nr * m + nc;
                }
            }
        }
