import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();
        int q = sc.nextInt();
        long INF = (long) 1e18;
        long[][] d = new long[n + 1][n + 1];
        for (int i = 1; i <= n; i++) {
            Arrays.fill(d[i], INF);
            d[i][i] = 0;
        }
        for (int i = 0; i < m; i++) {
            int u = sc.nextInt(), v = sc.nextInt();
            long w = sc.nextLong();
            if (w < d[u][v]) {
                d[u][v] = d[v][u] = w;
            }
        }
        for (int k = 1; k <= n; k++) {
            for (int i = 1; i <= n; i++) {
                if (d[i][k] == INF) continue;
                for (int j = 1; j <= n; j++) {
                    if (d[k][j] != INF && d[i][k] + d[k][j] < d[i][j]) {
                        d[i][j] = d[i][k] + d[k][j];
                    }
                }
            }
        }
        StringBuilder sb = new StringBuilder();
        while (q-- > 0) {
            int u = sc.nextInt(), v = sc.nextInt();
            sb.append(d[u][v] >= INF ? -1 : d[u][v]).append('\n');
        }
        System.out.print(sb.toString());
    }
}

