        int n = sc.nextInt();
        int[] parent = new int[n + 1];
        int[] deg = new int[n + 1];
        for (int i = 2; i <= n; i++) {
            parent[i] = sc.nextInt();
            deg[parent[i]]++;
        }
        int[] sub = new int[n + 1];
        Queue<Integer> q = new ArrayDeque<>();
        for (int i = 1; i <= n; i++) {
            if (deg[i] == 0) q.add(i);
        }
        while (!q.isEmpty()) {
            int u = q.poll();
            if (u == 1) break;
            int p = parent[u];
            sub[p] += sub[u] + 1;
            if (--deg[p] == 0) q.add(p);
        }
        StringBuilder sb = new StringBuilder();
        for (int i = 1; i <= n; i++) {
            if (i > 1) sb.append(' ');
            sb.append(sub[i]);
        }
        System.out.println(sb.toString());
