public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        long mod = 1000000007L;
        StringBuilder sb = new StringBuilder();
        while (n-- > 0) {
            long a = sc.nextLong();
            long b = sc.nextLong();
            long res = 1;
            a %= mod;
            while (b > 0) {
                if ((b & 1) == 1) res = (res * a) % mod;
                a = (a * a) % mod;
                b >>= 1;
            }
            sb.append(res).append('\n');
        }
        System.out.print(sb.toString());
    }
}

